{"t":"step","id":"retrieve-policy","kind":"knowledge","label":"Retrieve approved policies","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","repeat":"per-question","why":"Find relevant approved policy chunks for each question"}
{"t":"step","id":"rank-policy","kind":"knowledge","label":"Rank policy evidence","task":"rerank","ai":"qwen3-rerank","runs":"fc","repeat":"per-question","after":"retrieve-policy","why":"Score retrieved chunks by relevance to reduce noise"}
{"t":"step","id":"draft-answer","kind":"ai","label":"Draft grounded answer","task":"generate","ai":"qwen3.7-plus","runs":"agentrun","repeat":"per-question","after":"rank-policy","why":"Generate an answer strictly based on ranked policy evidence"}
