{"t":"link","id":"draft-guard","from":"draft-proposal","to":"guard-output"}
{"t":"link","id":"guard-approve","from":"guard-output","to":"approve-rebook"}
{"t":"link","id":"approve-execute","from":"approve-rebook","to":"execute-rebook","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-declined","from":"approve-rebook","to":"end-declined","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"approve-rebook","to":"draft-proposal","kind":"branch","outcome":"edit"}
{"t":"link","id":"execute-notify","from":"execute-rebook","to":"notify-traveler"}
{"t":"link","id":"notify-log","from":"notify-traveler","to":"log-result"}
{"t":"link","id":"log-end","from":"log-result","to":"end-approved"}
{"t":"done","summary":"SchedulerX-triggered agent monitors flights via MCP, drafts rebooking proposals, gates execution behind CloudFlow human approval, then notifies travelers."}

{"t":"say","text":"Prompt chain pattern: OCR parsing, regulation retrieval, risk flagging, and human approval before submission."}
{"t":"assume","id":"dest-country","text":"Destination country is extracted from invoice or metadata","alt":"Destination country provided via trigger payload"}
{"t":"assume","id":"regulations-store","text":"Regulations stored in DashVector for semantic retrieval","alt":"Regulations fetched via external API tool"}
