{"t":"ask","id":"volume","text":"How many invoice and packing list sets are processed per day?"}
{"t":"ask","id":"success","text":"What defines a successful clearance, and what is today's baseline rejection rate?"}
{"t":"step","id":"upload-trigger","kind":"trigger","label":"Invoice upload received","runs":"fc","untrusted":true,"why":"Entry point for uploaded customs documents"}
