{"t":"link","id":"dest-retrieve","from":"identify-dest","to":"retrieve-regs","kind":"next","label":"Country identified"}
{"t":"link","id":"retrieve-rank","from":"retrieve-regs","to":"rank-regs","kind":"next","label":"Docs fetched"}
{"t":"link","id":"rank-check","from":"rank-regs","to":"compliance-check","kind":"next","label":"Top regs selected"}
{"t":"link","id":"check-risk","from":"compliance-check","to":"risk-flag","kind":"next","label":"Check complete"}
{"t":"link","id":"risk-report","from":"risk-flag","to":"compile-report","kind":"next","label":"Risks flagged"}
{"t":"link","id":"report-output-guard","from":"compile-report","to":"output-guard","kind":"next","label":"Report drafted"}
{"t":"link","id":"output-approve","from":"output-guard","to":"officer-approve","kind":"next","label":"Report screened"}
{"t":"link","id":"approve-submit","from":"officer-approve","to":"submit-customs","kind":"branch","outcome":"approve","label":"Officer approved"}
{"t":"link","id":"approve-rejected","from":"officer-approve","to":"rejected","kind":"branch","outcome":"reject","label":"Officer rejected"}
{"t":"link","id":"approve-edit","from":"officer-approve","to":"compile-report","kind":"branch","outcome":"edit","label":"Request revision"}
{"t":"link","id":"submit-done","from":"submit-customs","to":"submitted","kind":"next","label":"Submission sent"}
{"t":"done","summary":"Designed prompt-chain workflow for customs document parsing, regulation checking, risk flagging, and officer approval before submission."}

